#include "gtest/gtest.h"
#include "population/population.hpp"
#include "../../tests/gtest/test_population_test_fixture.hpp"

namespace {
// Total mortality Z = M + sum over fleets of F * f_multiplier * selectivity,
// built from the fixture inputs instead of the model's mortality_Z.
double ExpectedTotalMortality(
    std::shared_ptr<fims_popdy::Population<double>>& population, int year,
    int age) {
  int i_age_year = year * population->n_ages + age;
  double total_mortality = exp(population->log_M[i_age_year]);
  for (size_t fleet_index = 0; fleet_index < population->n_fleets;
       fleet_index++) {
    auto& fleet = population->fleets[fleet_index];
    total_mortality += exp(fleet->log_Fmort[year]) *
                       exp(population->log_f_multiplier[year]) *
                       fleet->selectivity->evaluate(population->ages[age]);
  }
  return total_mortality;
}

// CatchAtAge_CalculateNumbersAA
// IO correctness
TEST_F(CAAEvaluateTestFixture,
       HandlesCorrectInput_CatchAtAge_CalculateNumbersAA) {
  size_t pop_id = population->GetId();
  auto& dq = catch_at_age_model->GetPopulationDerivedQuantities(pop_id);

  // Fish of age a - 1 in year y - 1 survive to age a in year y
  double expected_naa =
      dq["numbers_at_age"][i_agem1_yearm1] *
      exp(-ExpectedTotalMortality(population, year - 1, age - 1));

  EXPECT_NEAR(dq["numbers_at_age"][i_age_year], expected_naa,
              1e-10 * expected_naa);
  EXPECT_GT(dq["numbers_at_age"][i_age_year], 0);
}

// Edge handling
TEST_F(CAAEvaluateTestFixture, HandlesEdgeCase_CatchAtAge_CalculateNumbersAA) {
  int year = 4;
  int age = population->n_ages - 1;
  int i_age_year = year * population->n_ages + age;
  int i_agem1_yearm1 = (year - 1) * population->n_ages + age - 1;

  size_t pop_id = population->GetId();
  auto& dq = catch_at_age_model->GetPopulationDerivedQuantities(pop_id);

  catch_at_age_model->CalculateNumbersAA(population, i_age_year, i_agem1_yearm1,
                                         age);

  // The plus group holds survivors of the second-oldest age plus survivors
  // of the plus group itself, each with its own total mortality
  double expected_naa =
      dq["numbers_at_age"][i_agem1_yearm1] *
          exp(-ExpectedTotalMortality(population, year - 1, age - 1)) +
      dq["numbers_at_age"][i_agem1_yearm1 + 1] *
          exp(-ExpectedTotalMortality(population, year - 1, age));

  EXPECT_NEAR(dq["numbers_at_age"][i_age_year], expected_naa,
              1e-10 * expected_naa);
  EXPECT_GT(dq["numbers_at_age"][i_age_year], 0);
}
}  // namespace